const key=new URLSearchParams(location.search).get('service');const item=services[key]||services.architecture;
function render(lang,updateUrl=false){if(!['en','fa','ar'].includes(lang))lang='en';document.documentElement.lang=lang;document.documentElement.dir=lang==='en'?'ltr':'rtl';document.querySelectorAll('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));document.querySelectorAll('[data-ui]').forEach(el=>el.textContent=ui[lang][el.dataset.ui]);const d=item[lang];document.title=d[0]+' — Fourth Dimension Studio';document.querySelector('meta[name="description"]').content=d[1];serviceIndex.textContent=item.n+' / SERVICE';serviceIcon.textContent=item.icon;serviceTitle.textContent=d[0];serviceIntro.textContent=d[1];deliverables.innerHTML=d[2].map(x=>'<li>'+x+'</li>').join('');process.innerHTML=d[3].map(x=>'<li>'+x+'</li>').join('');serviceCta.href='mailto:hello@fourthdimension.studio?subject='+encodeURIComponent(d[0]);if(updateUrl){const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState({},'',url)}}
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>render(b.dataset.lang,true));render(new URLSearchParams(location.search).get('lang')||'en');
